def render(hass, template, variables=None, **kwargs):
    """Render given template."""
    if variables is not None:
        kwargs.update(variables)
    location_methods = LocationMethods(hass)
    utcnow = dt_util.utcnow()
    try:
        return ENV.from_string(template, {'closest': location_methods.
            closest, 'distance': location_methods.distance, 'float':
            forgiving_float, 'is_state': hass.states.is_state,
            'is_state_attr': hass.states.is_state_attr, 'now': dt_util.
            as_local(utcnow), 'states': AllStates(hass), 'utcnow': utcnow}
            ).render(kwargs).strip()
    except jinja2.TemplateError as err:
        raise TemplateError(err)

